/* ============ i18n (safe) ============ */
(function (g) {
  function isPlainObject(o){return Object.prototype.toString.call(o)==="[object Object]";}
  function getDict(){const src=g.languageData||g.data||{};return isPlainObject(src)?src:{};}
  function getByPath(obj,path){const parts=path.split(".");let cur=obj;for(let i=0;i<parts.length;i++){const k=parts[i];if(!isPlainObject(cur)&&!Array.isArray(cur))return; if(!Object.prototype.hasOwnProperty.call(cur,k))return; cur=cur[k];}return cur;}
  g.l_js__=function(key){try{if(typeof key!=="string")return String(key);if(key.length>200)key=key.slice(0,200);
    const dict=getDict();const val=key.includes(".")?getByPath(dict,key):Object.prototype.hasOwnProperty.call(dict,key)?dict[key]:undefined;
    if(typeof val==="string")return val; if(typeof val==="number"||typeof val==="boolean")return String(val); return key;}catch(_){return key;}};
})(window);

/* ============ Helpers ============ */
const debounce=(fn,ms=300)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms);};};
function setCookie(k,v,days=365){const d=new Date();d.setTime(d.getTime()+days*24*60*60*1000);const https=location.protocol==="https:";document.cookie=`${encodeURIComponent(k)}=${encodeURIComponent(v)}; expires=${d.toUTCString()}; path=/; SameSite=Lax`+(https?"; Secure":"");}
function getCookie(k){const m=document.cookie.split("; ").find(c=>c.startsWith(encodeURIComponent(k)+"="));return m?decodeURIComponent(m.split("=")[1]):"";}
function bsShow(idOrEl){const el=typeof idOrEl==="string"?document.getElementById(idOrEl):idOrEl;if(!el)return;try{if(window.bootstrap?.Modal)window.bootstrap.Modal.getOrCreateInstance(el).show();else{el.classList.add("show");el.style.display="block";el.removeAttribute("aria-hidden");}}catch(e){console.error(e);}}
function getCsrfToken(){const meta=document.querySelector('meta[name="csrf-token"]');if(meta?.content)return meta.content;const inp=document.querySelector('input[name="csrf_token"]');if(inp?.value)return inp.value;if(typeof window.CSRF_TOKEN==="string"&&window.CSRF_TOKEN)return window.CSRF_TOKEN;return "";}

/* ============ Dil verisi yükle ============ */
function loadLanguageData(cb){
  fetch("/?api=i18n&_="+Date.now(),{credentials:"same-origin",cache:"no-store"})
    .then(r=>r.json()).then((data)=>{
      const cur=(data&&(data.currentLanguage||data.lang||""))||window.currentLanguage||document.documentElement.lang||"EN";
      window.currentLanguage=cur; try{document.documentElement.lang=String(cur).toLowerCase();}catch{}
      window.languageData=(data&&(data.languageData||data.languageDataJS||data.data))||window.languageData||{};
      try{window.dispatchEvent(new Event("languageData:ready"));}catch{} if(typeof cb==="function")cb(data||{});
    }).catch(()=>{if(typeof cb==="function")cb({});});
}
loadLanguageData(function(){});

/* ============ Tema ============ */
(function(){
  document.addEventListener("DOMContentLoaded",function(){
    const sw=document.getElementById("mySwitch"); const saved=localStorage.getItem("theme");
    const applyTitle=(isDark)=>{if(!sw)return; const text=isDark?(sw.getAttribute("light")||""):(sw.getAttribute("dark")||""); if(text)sw.setAttribute("data-bs-title",text);else sw.removeAttribute("data-bs-title"); const tip=window.bootstrap?.Tooltip?.getInstance(sw); if(tip?.setContent)tip.setContent({".tooltip-inner":text||""}); else tip?.update();};
    const initial=saved!==null?(saved==="true"):!!(sw&&sw.checked);
    document.documentElement.setAttribute("data-bs-theme",initial?"dark":"light"); if(sw)sw.checked=initial; applyTitle(initial);
    const requestURL=window.location.pathname.split("/").pop();
    const update=(isDark)=>{const t=isDark?"dark":"light"; document.documentElement.setAttribute("data-bs-theme",t); sw&&(sw.checked=isDark); localStorage.setItem("theme",isDark); applyTitle(isDark);
      fetch(requestURL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({theme_s:isDark,csrf_token:getCsrfToken()})}).then(r=>r.json()).catch(()=>{});};
    sw?.addEventListener("change",function(){update(this.checked);});
  });
})();

/* ============ Offcanvas dil/tema taşıma ============ */
(function(){
  document.addEventListener("DOMContentLoaded",function(){
    const off=document.getElementById("offcanvasSidebar");
    off?.addEventListener("show.bs.offcanvas",function(){
      const c=document.getElementById("offcanvasSidebarContent"); const inline=document.getElementById("sidebarContent");
      if(c&&inline&&inline.innerHTML.trim()!==""){c.innerHTML=inline.innerHTML;}
    });
    const node=document.getElementById("langDarkSelectionContent"); if(!node)return; const parent=node.parentNode; const next=node.nextElementSibling;
    function place(){ if(window.innerWidth<992){const oc=document.getElementById("langDarkSelectionOffcanvasContent"); if(oc&&node.parentNode!==oc)oc.appendChild(node);}
      else if(parent&&node.parentNode!==parent){ if(next)parent.insertBefore(node,next); else parent.appendChild(node);} }
    place(); window.addEventListener("resize",place);
  });
})();

/* ============ API helper (global) ============ */
const HAMU_API_URL="/?api=config&_prj=1";
function postProject(action,data={},files=null){
  const fd=new FormData(); fd.append("_hamu_project","1"); fd.append("action",action); fd.append("csrf_token",getCsrfToken());
  Object.entries(data||{}).forEach(([k,v])=>{if(v!==undefined&&v!==null)fd.append(k,v);});
  if(files&&typeof files==="object")Object.entries(files).forEach(([k,v])=>v&&fd.append(k,v));
  return fetch(HAMU_API_URL,{method:"POST",body:fd,credentials:"same-origin",headers:{"X-Requested-With":"XMLHttpRequest"}})
    .then(r=>{if(!r.ok)throw new Error("Network "+r.status);return r.json().catch(()=>({}))})
    .then(j=>{if(j&&(j.ok||j.success||j.status==="ok"))return j; throw new Error(j?.msg||j?.error||l_js__("unexpected_response"));})
    .catch(e=>({success:false,message:e.message||l_js__("request_error")}));
}

